            if keks>0:
                return 0
            return -999
    else:
        if (amount >= 0):
            self.DBcursor.execute(u"INSERT INTO kekse (nickname, count, item) VALUES (?, ?, ?)", (name, amount, item))
            self.DBconn.commit()
            return amount
        else:
            return -999;

