def delete_asset_queued_events(
    *, uri: str, before: str | None = None, session: Session = NEW_SESSION
) -> APIResponse:
    """Delete queued asset events for an asset."""
    permitted_dag_ids = get_auth_manager().get_permitted_dag_ids(methods=["GET"])
